quests[93767] = { id = 93767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Arcantina", description = "The Arcantina welcomes all who seek respite.\n\nStep inside its lively halls, share a brew, and trade stories with friends old and new. \n\nWhere the Void brings chill and silence, here you'll find warmth, laughter, and the spark of fellowship.", completion = "Ah, you've returned. I am glad you allowed yourself that well-earned moment of peace.", objectives = "Visit the Arcantina and have a brew with one of the patrons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93769] = { id = 93769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Housing", description = "A strong community is built not by walls, but by the hands and hearts of those within it. \n\nLend your voice, your time, and your spirit to the neighborhood. Help your fellows, share in their burdens, and take your place as an active part of the home we build together.You will learn:", objectives = "Participate in neighborhood Endeavors and collect Community Coupons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93771] = { id = 93771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'kuai, Village of Rain", description = "All waters in Harandar are sacred. They feed the roots of the world and Aln'hara's myriad creations in equal measure. Perhaps none are more spectacular than those that fall from the roots of the tree called Nordrassil.\n\nTo the north, you will find Har'kuai. The rains that fall from the sky there carry a remarkable vitality. If you wish to witness all of Aln'hara's majesties, then a trek to Har'kuai would serve you well.", completion = "I have heard of your travels, outsider. I am Kamari, Rootwarden of Nordrassil.\n\nThe mists of Har'kuai hold many mysteries. I hope you will find them enlightening, during your stay here.", objectives = "Meet Rootwarden Kamari in Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93774] = { id = 93774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When is a Chair not for Sitting?", description = "Aethas Sunreaver, Riftblade Maella, and Auric Sunchaser have recently revitalized an old arcane twist on hide and seek called Decor Duel.\n\nThey're looking for new participants to help spread the entertainment.\n\nYou should meet them over in Falconwing Square.", sourceObjective = "Speak with Riftblade Maella in Falconwing Square.", completion = "Greetings! Are you here to learn more about our joint venture?", sourceObjectiveStatus = "unverified-source-field" }
quests[93775] = { id = 93775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'mara, Village of Balance", description = "Ah! The outsider who saved Har'mara. Word travels fast through Aln'hara's roots. No doubt Elder Hagar was grateful for your aid.\n\nShe would never admit it, but things have been difficult since the roots above her village burned. The rutaani and fungarians each grow bolder in their eccentricities. And the lingering flare-ups on Teldrassil's roots present a constant threat.\n\nIf your travels afford another trip to Har'mara, I do not doubt she would benefit from additional help.", completion = "Ah! {name}. Welcome back. As you can see, our hands are full as ever, here.\n\nI assure you, I have things well in hand. But if you do wish to explore a bit further afield, I am sure some of the others could benefit from your assistance.", objectives = "Return to Hagar in Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93776] = { id = 93776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'alnor, Village of Twilight", description = "Our efforts in the Blinding Bloom have halted the Lightbloom's encroachment for now. But with Rootwarden Ruia gone, there are scarce few who remain to handle the rest of the village's troubles.\n\nI'm going back to Har'alnor to help out where I can. If you have the time and the inclination, your further assistance would be most appreciated.", completion = "Thank the goddess you returned.\n\nAs you can see, we're still in fairly dire straits here. Though we quelled its spread beneath Shaladrassil's roots, the Lightbloom remains a threat. There are rumors of fungarians acting erratically in Fungara Village. And there is no Rootwarden in Har'alnor to deal with either.\n\nThankfully, we have the next best thing: an intrepid outsider with a habit of helping others.", objectives = "Meet with Hannan in Har'alnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93782] = { id = 93782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Multiple Objectives, Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93783] = { id = 93783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Just One Objective", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93784] = { id = 93784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnawing Void of Curiosity", description = "<The artifact crumbles in your hand, leaving only a faint but distinctly ancient arcane footprint. Naleidea Rivergleam will want to hear about this.>", sourceObjective = "Report your discovery to Naleidea Rivergleam in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[93792] = { id = 93792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Loa", description = "My name is Du'gal. And you are hash'ura.\n\nKinduru has ordered me to train you in de ways of loa worship. Take honor in it. Very few gokinye have earned de right as you have.\n\nBeside me is de Altar of Blessings. You may use it to worship any of our loa, and you shall receive a sliver of power in thanks.\n\nGo ahead now, if ya be so kind.", progress = "De loa are quite generous indeed.", completion = "Ya spirit is flowing with strength!\n\nYou may use de altar as often as ya wish. But ya can only hold one blessing on ya self at a time.", objectives = "Worship at the Altar of Blessings.\n\nGain a blessing by choosing to combine the power of Akil'zon, Halazzi, Jan'alai, or Nalorakk with that of any lesser loa you've formed a bond with.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93798] = { id = 93798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with Zul'jarra's Forces", description = "Dis struggle would have been lost ages ago without you on our side. Now, we live to fight another day.\n\nZul'jarra wishes to honor your efforts with a gift. Come speak to me in Tokka's Landing to receive it.", sourceObjective = "Speak with Jan'sari the Watchful at Tokka's Landing.", sourceObjectiveStatus = "unverified-source-field" }
quests[93801] = { id = 93801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calculated Culling", description = "This pathogen is spreading rapidly among the denizens of the Molt.\n\nA swarm of netherwasp hatched shortly after our arrival. The infection spread throughout the region as they fought over territory. If their numbers continue to grow, they could carry the pathogen to the rest of Voidstorm.\n\n{name}, can I ask you to reduce the number of infected creatures in the Molt?", progress = "This place has such vitality. It's no wonder the pathogen has spread so easily.", completion = "Your efforts and assistance are both noted and appreciated.", objectives = "Cull creatures endemic to the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93810] = { id = 93810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masters' Perch", description = "Not every creature of the Void serves Xal'atath's whims. Conquest was our way long before her arrival.\n\nTo the north, you find Slayer's Rise. It is the vast battleground where three domanaar vie for power. And I hear your ren'dorei allies have set up in Masters' Perch, the main citadel, as well.\n\nI am certain great battles await you there. Go forth.", completion = "Good, we need more capable arms.", objectives = "Seek void elf allies in Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93811] = { id = 93811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Silvermoon Court", description = "The people of Quel'thalas appreciate your continued support. With threats on all sides, it is good to know we can rely on champions such as yourself to protect us.\n\nThe Court wishes to reward you for your efforts.", sourceObjective = "Speak with Caeris Fairdawn at Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[93816] = { id = 93816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting it Together", description = "You have the basics now. All that's left is to experience the Arcane Propagator for yourself in a match of Decor Duel!\n\nWhat is the Arcane Propagator, you ask? A mystic relic wrought from glamours. It lets players cloak themselves in the guise of enchanted objects.\n\nWe've partially recreated it with the chair for training, as you've seen, but the real thing is much better. Why not play a match for real right now?", sourceObjective = "Speak with Fieldweaver Amolenne to enter a match of Decor Duel, then speak with Propagandist Naicira.", progress = "{name}? No, I do not see your name on any of the game rosters.\n\nSpeak with Gamemaster Fleurian to join a game of Decor Duel.", completion = "Splendid! Well done out there, {name}!\n\nYou did well! And there are even more abilities and other Kits for you to discover and learn.", sourceObjectiveStatus = "unverified-source-field" }
quests[93841] = { id = 93841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghosts of the Ring", description = "I was at de Ring of Glory earlier. Have you been? De place is crawlin' with spirits and one of dem gave me quite de fright! Came right up and tried to talk to me! I was too nervous to stick 'round and find out what he wanted.\n\nYou look brave and strong. Maybe you oughta check it out.", sourceObjective = "Find Ja'bonu at the Ring of Glory.", completion = "Who? Ah, I remember de priest now. He screamed very loudly when I tried to talk to him. It's been a while since I laughed dat hard.\n\nYou here to help?", sourceObjectiveStatus = "unverified-source-field" }
quests[93842] = { id = 93842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloom and Fade", description = "My time is runnin' out and I need to see if I can rescue my beloved, Eshaye. She's stuck in de loop, and I want to break her from de cycle before I fade entirely.\n\nI used to be able to get through to her with bouquets of sweetsaw blooms. I can't grasp dem anymore, though. Will you gather some for me?", sourceObjective = "Collect 6 Sweetsaw Blooms around the Ring of Glory.", progress = "I think de scent of de blooms always brought her back. I can't smell anything anymore. If she also can't, maybe nothing gonna bring her back.", completion = "Are dey not beautiful?\n\n<He leans close, inhaling, but then sighs disappointedly.>\n\nI cannot smell dem. I wish I could have, one more time. Hopefully Eshaye still can.", sourceObjectiveStatus = "unverified-source-field" }
quests[93843] = { id = 93843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ectoplasmic Extractions", description = "Up near de Ring of Glory, there are spirits like myself who are merchants. Dey sell a variety of things to other spirits, but I got Eshaye's attention in de past using a beverage from Mab'jul.\n\nDe market goods can be purchased with ectoplasm, which can be gathered from de frayed spirits around de Ring. Especially de cultists, who steal it from de others.", sourceObjective = "Collect 20 Ectoplasm.", progress = "At first, we just wandered in de swamp: confused, angry, hurtin', scared. After many thousands of years, some learned how to transmute de ectoplasm left behind when another spirit is sundered. Dis currency began to be quite sought after.\n\nYou cannot destroy a spirit here entirely. Eventually, it will reform itself, but it takes a very long time. Since none of us can move on, there's always a supply of ectoplasm, though gatherin' is difficult. Were you able to procure enough?", completion = "You done well. We are one step closer to breakin' Eshaye free from de loop.", sourceObjectiveStatus = "unverified-source-field" }
quests[93849] = { id = 93849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ectoplasmic Emporium", description = "Eshaye is sure to love these flowers! Now all we need is de spectral brew. Take de ectoplasm to Mab'jul and exchange it for a bottle of spectral brew.\n\nIt's a vintage made from harvested ectoplasm, and is quite refreshing. It sometimes has de ability to stall fraying.", sourceObjective = "Bring the bouquet and brew to Eshaye.", progress = "I remember de first time I gave her flowers. I didn't think a warrior like her could blush, but she did. I hope I never forget her smile dat day.", completion = "I see. Been too long since I last gave her flowers. Her memory of dem, and of our time together, may be long gone.", sourceObjectiveStatus = "unverified-source-field" }
quests[93850] = { id = 93850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrunner Spire: Haunting Melodies", description = "So much grief... So much pain. It binds us to this place.\n\nHis melodies once soothed us, but now they are drowned out by the din of violence.\n\nPlease help us. Follow the sound of the lyre. He will guide you.", progress = "Please... help us.", completion = "The pain, the fear... I can feel that music washing it all away.\n\nThank you, friend.", objectives = "Quell the restless spirits inside Windrunner Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93851] = { id = 93851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Communing with Ghosts", description = "Dat was a long shot, but I still wanted to try.\n\n<He pauses a moment and shudders, seeming to flicker at the edges.>\n\nI am out of ideas, {name}. Will you ask around? Some of de others here may have some ideas of how to get through to Eshaye. I am not welcome too close to dem, or I would come with you.", sourceObjective = "Talk to ghosts around the Ring of Glory.", progress = "I hope one of dem has some ideas. I am running out of time.", completion = "Challenge Eshaye? Of course! Why didn't I think of dat?\n\nErm, probably because I can't beat her.", sourceObjectiveStatus = "unverified-source-field" }
quests[93852] = { id = 93852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Iridescent Flightstone", description = "The flightstone glimmers with the colors of all aspects. Within the glittering light you have visions of noble dragon houses locked in battle against Primal Incarnates. A vicious cacophony of roars as Shadowflame consumes swaths of land. And the soothing sounds of nature as a world tree blooms.\n\nThe soaring skies of Valdrakken call.", sourceObjective = "Bring the Lost Iridescent Flightstone to Xydan in Valdrakken.", completion = "A relic of a time passed. It glimmers with the shine of all of the dragonflights, a solemn reminder of the beauty and strength when we come together.", sourceObjectiveStatus = "unverified-source-field" }
quests[93865] = { id = 93865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carve Your Way", description = "We permit the presence of your kind for one reason. Your willingness to fight. Show us the skills of mortal duelists.\n\nGo, find others of your kind. The pit below is an ideal site for demonstrations of combat prowess.", progress = "Go. Show me a bout.", completion = "Good. But one victory proves nothing. The path to supremacy requires sustained practice.\n\nReturn tomorrow and demonstrate your skills further.", objectives = "Win a duel against another player or the Masters' Champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93870] = { id = 93870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ephemeron Masquerade", description = "The deeds of today becomes the tales of dusk!\n\nSeekers and Hiders, alike, make their mark through thrilling game play and strategic out maneuvering.\n\nThe sun shines its light on a new day, shattering the illusions of yesterday, and elongating the shadows of today. Are you ready?\n\nDon you disguise, secure your kit, and show your peers no one can hold a candle to you ... literally!", sourceObjective = "Speak with Fieldweaver Amolenne to play Decor Duel.", progress = "Your task remains incomplete, {name}.", completion = "Ah, well done! I watched you out there, and it was quite thrilling!", sourceObjectiveStatus = "unverified-source-field" }
quests[93877] = { id = 93877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Sequential", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93878] = { id = 93878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Multiple Steps, No Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93879] = { id = 93879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Conditional After Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93889] = { id = 93889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Saltheril's Soiree", description = "Champion, you would do well to attend Saltheril's Soiree.\n\nThere, amidst Silvermoon's intricate politics and quiet struggles for influence, our most distinguished military orders each have matters they wish to see addressed.\n\nProve your worth to these factions, and you may find their gratitude and favor richly rewarded.", completion = "You've done well to navigate the Court without being swallowed by its politics. Silvermoon needs those who can act with purpose, not those lost in the machinery of ambition.", objectives = "Participate in Saltheril's Soiree and earn favor with one of the Silvermoon factions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93890] = { id = 93890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Abundance", description = "The trolls of Zul'Aman draw their strength from the loa: ancient spirits that grant power to those who honor them. These boons can be wondrous or perilous, depending on the loa's nature and the devotion of its followers.\n\nThere are whispers of a Loa of Abundance dwelling within Zul'Aman, its blessings said to bring prosperity to those deemed worthy.\n\nSeek it out, learn what drives it, and see if its favor would serve our cause.You will learn:", objectives = "Participate in Zul'Aman's Abundance Harvest and gain Loa's favor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93891] = { id = 93891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Legends of the Haranir", description = "For the Haranir, art is a language of memory. \n\nTheir history endures not in words but in vivid stories painted upon stone with pigments imbued with power. Through these works, the Zur'ashar, their revered historians, entwine living visions of the past to the present. Each vision draws us deeper into the haranir's mysteries, guiding us closer to the truths that shaped their world.You will learn:", sourceObjective = "Step into the memories of the Haranir through the enchanted paintings.", sourceObjectiveStatus = "unverified-source-field" }
quests[93892] = { id = 93892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Stormarion Assault", description = "The fight against Xal'atath tests our resolve, but it will not break us.\n\nVoid anomalies twist the halls of Stormarion Citadel, but they will find no weakness here. The Void Elves stand as our allies. Prove to our enemies that our strength when united is beyond the reach of even the Void.\n\nGo, {name}--aid them, and see the Citadel cleansed of corruption.You will learn:", objectives = "Participate in the Stormarion Assault event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93899] = { id = 93899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slayer's Rise", description = "We've received reports of escalated troubles between some domanaar. Go investigate the battle in Slayer's Rise, then report to Deminos Darktrance in Masters' Perch.", completion = "{name}, you made it through. Well done.", objectives = "Complete the Slayer's Rise battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93904] = { id = 93904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defying Gravity", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", objectives = "Gather Void energy within the Lair of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93905] = { id = 93905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongoing Stoppage", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", objectives = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93906] = { id = 93906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untethering the Two", description = "It never occurred to me to attack Eshaye. I been wasting time tryin' to get her to talk to me, without knowin' how to talk to her.\n\nWill you do dis for me? Challenge Eshaye and beat her. Could dis wake her up? I feel hope stirrin'.", sourceObjective = "Help Eshaye regain her awareness.", completion = "Thank you for snapping me out of dat cycle, {name}. All I could remember was seeking victory on de day we were killed. I didn't remember what I was fighting for: to return to Ja'bonu and de life we shared.\n\nI feel complete and whole for de first time in thousands of years. Whatever it was dat trapped us here, it cannot hold me and Ja'bonu any longer. We can move on now, to de next adventure, together.", sourceObjectiveStatus = "unverified-source-field" }
quests[93907] = { id = 93907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edification of the Worthy", description = "When you acquire a new Seeker kit, it always starts off relatively lean.\n\nBut you'll earn Illusionary Coins as you play, and may trade them in with Gamemaster Fleurian for expanded abilities, and even additional kits!\n\nTake these. Add them to what you earned and demonstrate your shopping prowess.", sourceObjective = "Use Illusionary Coins with the vendor, Gamemaster Fleurian, to purchase something.", progress = "Those coins were a one-time gift, {name}. If you have mislaid them, or have suffered the misfortune of thievery, then I suppose you will have to enter the games to collect more.", completion = "Excellent! Great work, {name}. Don't forget to check in often! You'll want to make sure you unlock the full potential of all the Kits available in order to maximize your enjoyment--and points-earning potential, of course.", sourceObjectiveStatus = "unverified-source-field" }
quests[93909] = { id = 93909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Delves", description = "Many have ventured into the delves' depths, but few have returned with more than dust and bruises.\n\nValeera Sanguinar has taken a keen interest in these ventures. She leaves no stone unturned and has a remarkable talent for getting in to places others cannot.\n\nSeek her out, and see what fortune or danger awaits beneath the surface.", progress = "Stay sharp, {name}.", completion = "You've braved the delves and returned stronger for it.\n\nValeera was right--opportunity favors the bold.", objectives = "Complete 3 Delves in Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93910] = { id = 93910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Prey", description = "Silvermoon is beset on all sides by threats both known and unknown. There are those who seek to track these threats and put an end to the strife and chaos they create.\n\nSpeak with Magister Astalor Bloodsworn in Murder Row. He will guide you toward the urgent threats.You will learn:", objectives = "Complete Prey Hunts for Astalor Bloodsworn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93911] = { id = 93911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Dungeons", description = "The dungeons of Azeroth hold great challenges and even greater rewards. Within them lay treasures that may aid you in battles yet to pass, and powerful foes to overcome.\n\nEnter the dungeon, and see what awaits you there.", progress = "Be ready for anything. Fortune often walks hand in hand with peril.", completion = "You've proven your mettle once more. \n\nMay your victories within strengthen you for what lies ahead.", objectives = "Complete any Seasonal Dungeon at Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93912] = { id = 93912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Raid", description = "Gather your allies, you will face the great trials ahead. \n\nThe rewards are vast, and can aid you in the battles ahead. You and your allies need only vanquish a small number of these terrible foes.You will learn:", sourceObjective = "Defeat any 2 raid bosses in Midnight on any difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[93913] = { id = 93913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Boss", description = "Powerful enemies roam Azeroth, their strength growing with each passing battle.\n\nOnly through courage and unity will you emerge victorious.You will learn:", sourceObjective = "Defeat a World Boss in Midnight.", sourceObjectiveStatus = "unverified-source-field" }
quests[93922] = { id = 93922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Singular Focus Unleashed", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93923] = { id = 93923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenacity of the Shul'ka", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93924] = { id = 93924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unrelenting March", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93929] = { id = 93929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Within Recap", description = "<A parchment reaches you from an unknown sender.>\n\n<It speaks of perusing a tome to catch up on current events, and how it is vital to understand a looming threat.>\n\n<Perhaps you should seek out this tome to understand more when you are ready.>", completion = "<The tome floats in front of you. Its pages are filled with knowledge of all that has happened.>", objectives = "Consult the Tome of History to learn about the War Within saga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93930] = { id = 93930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Courting Success", description = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief.\n\n<Caeris laughs lightly behind his handkerchief.>\n\nNow, let me be professional. You are cordially invited to attend Saltheril's soiree.\n\nDon't embarrass yourself, {name}. The best of Silvermoon are watching.", completion = "I half expected you to run back home in tears! I hope you had a stunning time.", objectives = "Participate in Saltheril's Soiree and empower Eversong's runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93931] = { id = 93931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abundance of Wealth", description = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout.\n\nSeek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth.\n\nIf nothing else, de rewards he grants are glorious--to de worthy, at least.", progress = "Did you find de loa, hash'ura?", completion = "Heh! So ya finally met Dundun.\n\nEven de smallest are some of de greatest among de loa!", objectives = "Harvest wealth for the Loa of Abundance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93932] = { id = 93932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Prosperity", description = "Harandar hides wisdom in every annal of its history, {name}. You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", completion = "I wonder what it is that the stones showed you. I hope you found it enlightening, {name}. But remember: there is always more to learn.", objectives = "Discover a legend of the Haranir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93933] = { id = 93933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guarded Treasures", description = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are.\n\nThere is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item.\n\nBut first, we must ensure it does not fall into the hands of our enemies.", progress = "Have you defended the anchor from the encroaching void forces?", completion = "Well done, {name}.", objectives = "Defend the Singularity Anchor in Stormarion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93938] = { id = 93938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spellbreaker's Oath", description = "To seek what is hidden.\n     To find the unseen.\nTo dispel all illusion\n     And glamours serene.\n\nSpellbreakers dispell\n     All truth is revealed.\nNo illusions endure,\n     No secret concealed.", sourceObjective = "lay as a Spellbreaker for Three Unbroken Minutes", sourceObjectiveStatus = "unverified-source-field" }
quests[93939] = { id = 93939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullifier's Oath", description = "To seek what is hidden.\n     To find the unseen.\nTo nullify illusion\n     And glamours serene.\nNullifiers negate\n\n     Your masks cease to exist.\nNo illusions remain,\n     No secret persists.", sourceObjective = "Play as a Nullifier for Three Unbroken Minutes", sourceObjectiveStatus = "unverified-source-field" }
quests[93940] = { id = 93940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Ranger's Oath", description = "To seek what is hidden.\n     To find the unseen.\nTo pierce through illusion\n     And glamours serene.\n\n Rangers sunder and unravel\n     Disguises are seen through.\nNo illusions conceal you,\n     No secret holds true.", sourceObjective = "Play as an Arcane Ranger for Three Unbroken Minutes", sourceObjectiveStatus = "unverified-source-field" }
quests[93942] = { id = 93942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Radiance", description = "A vision of radiance permeates your mind.\n\nEldara Dawnrunner might have more information regarding these Sparks of Radiance.", completion = "This is a Spark of Radiance.\n\nEvery week, one of these sparks will appear while on your adventures. In its current state, it's rather useless, but acquiring more will allow you to craft powerful items. Reagents like these are malleable, robust, and the prize for many crafters.\n\nThis is a unique crafting material that can help an item achieve expertise beyond that of mortal ability.", objectives = "Speak to Eldara Dawnrunner in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93943] = { id = 93943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Combat Curio to your delve companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93945] = { id = 93945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Utility Curio to your delve companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93954] = { id = 93954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prestidigimotion", description = "Don your chosen disguise, take to the field, and traverse with cunning.\nCover as much ground as you dare before capture claims you.\n\nTo reach the goal unseen is ideal.\nThough, you may be Found thrice, so long as you are never Tagged.\n\nMove as illusion would move:\n    with nimble grace,\n       with stealthful flair,\n           with reckless finesse.\n\nThe path is open.\nBecome what you are not.", sourceObjective = "Move \"1,000 steps\" as a Hider without getting Tagged.", sourceObjectiveStatus = "unverified-source-field" }
quests[93955] = { id = 93955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feastform", description = "Don your edible disguise, then take to the field and sustain your illusion\n\nYou are the offering.\n    Not seeker.\n       Not hunter.\n          The summoned feast.\n\nMove as the banquet would move!\nLet your presence tempt, confuse, or deceive.\n\nYou must complete three full minutes of uninterrupted embodiment.\n\nThe path is open.\nBecome what you are not.", sourceObjective = "Play with a Food Disguise for Three Unbroken Minutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[93956] = { id = 93956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wroughtform", description = "Don your crafted disguise, then take to the field and sustain your illusion\n\nYou are the object.\n    Not seeker.\n       Not hunter.\n          The conjured form.\n\nMove as relic, ornament, or artifact would move!\nLet your presence mislead, blend, or vanish.\n\nYou must complete three full minutes of uninterrupted embodiment.\n\nThe path is open.\nBecome what you are not.", sourceObjective = "Play with a Non-Food Disguise for Three Unbroken Minutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[93965] = { id = 93965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Wranglin'", description = "Seems like you've got the spurs for this ride. Just takes a little gettin' used to is all.\n\nCritters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", completion = "You're back. Hope you found a critter you fancy.\n\nThere are plenty more where that came from. Reckon you'll wrangle 'em all? I leave that up to you.", objectives = "Capture a Wild Pet in any Midnight zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93969] = { id = 93969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Shot", description = "Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYa might be used to havin' varmints bash heads until one was weak enough to nab. Got a new way to try. All you need is a crate. You've got one, yeah?\n\nJust throw the crate from the start. It's mighty effective, I tell ya.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", objectives = "Capture a Wild Pet in any Midnight zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93970] = { id = 93970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Storm", description = "The urgent nature of our mission to these lands should not preclude us from embarking on new and meaningful research. Long have my people studied the void, and any opportunity to break new ground must be seized. \n\nOur scouts have been finding peculiar void manifestations throughout Voidstorm. If my hypothesis is correct, I believe we can use our host's facilities to further refine and understand these samples.", progress = "Please do not drop the sample.", completion = "Did you hear that? It most certainly did something! \n\nHuzzah!", objectives = "Help Anomander unlock the Research Console in Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93979] = { id = 93979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Memories", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", completion = "This is what we are fighting for, {name}. We can only save fragments of K'aresh, but we can prevent other worlds from sharing our dreadful fate.", objectives = "Meet Alleria and Locus-Walker at the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93997] = { id = 93997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Post Control", description = "Vidious is moving to claim Slayer's Rise, sending his proxies to occupy the Void Posts. I shall not be outmaneuvered.\n\nSeize full control of each of the Void Posts and eliminate any of Vidious's forces that try to stop you.", completion = "You have done well. Your loyalty has earned you a great prize.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93999] = { id = 93999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Post Control", description = "Ziadan vies for control of Slayer's Rise, sending her proxies out to seize the Void Posts. Show her two can play at this game.\n\nStrike quickly: seize control of the Void Posts, slaying any who stand in your way.", completion = "A difficult task, completed with skill. Your loyalty deserves a reward.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94005] = { id = 94005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellar Stash" }
quests[94012] = { id = 94012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lil' Strider", description = "Howdy, pardner. Folks at this here pet store asked for my help straighten' out this place. But while I was distracted, a hawkstrider chick I've been rearin' slipped out the front door. Prettiest purple plumes you ever did see.\n\nWould you do me the kindness of finding her and bringing her back for me? I take her for a stroll in the garden every so often. I'll betcha that's where you'll find her.", progress = "Ya find her?", completion = "Fine work. Even some of these handlers wouldn't have been able to track down that wily bird.", objectives = "Capture Tiff in the Gardens of Remembrance in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94031] = { id = 94031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones of My Soul", description = "Do you have time to break a curse, {class}?\n\nI'm what remains of a loa speaker of Gral. I kept de prisoners in line on Gral's Belly. But we crashed, I died, and de prisoners escaped.\n\nMy powers didn't work on de livin' anymore. But they did work on de captain, who'd died with me.\n\nTerrified of his anger at my failure, I set up a ritual to trap him in de ship using my own bones.\n\nMy soul has leeched into de bones after all this time, and now I can't move them. Would you bring my bones to me?", sourceObjective = "Gather Yl'mul's bones from around the Wreck of Gral's Belly.", progress = "This ritual was an odd one my teacher taught me a long, long time ago.\n\nI never thought I'd need to perform rituals as a ghost, but I couldn't imagine how angry de captain would become.", completion = "Gral's power, my soul... it's all here again. Thank you for returnin' my bones, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[94035] = { id = 94035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat for the Bones", description = "To move my soul out o' de bones and into me, I need to do a ritual.\n\nGral is de loa of many things, but mostly de sea. He's a shark. And he likes meat!\n\nGet meat from de sea creatures around here. It will be easier to perform de ritual with somethin' red and oozing to ground me.", sourceObjective = "Collect 50 Sea Creature Meat from around the Wreck of Gral's Belly.", progress = "Plenty of loa speakers of Gral use meat in their rituals. Movin' my soul out o' de bones will take a lot of meat. But I'm sure that's nothing to you, right {class}?", completion = "Perfect, perfect! You got enough meat there for these old bones.", sourceObjectiveStatus = "unverified-source-field" }
quests[94036] = { id = 94036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Final Prisoner", description = "I cannot pretend I am any better than de captain.\n\nWe both enjoyed lording our power over de prisoners. When he'd lash out, I did not stop him.\n\nBut in our time trapped here together, I've reflected. De minute I wasn't useful to him, he got angry. And now I want this to end.\n\nI cannot enable him any more. Would you put him to rest?", sourceObjective = "Kill Captain Sal'chatah inside the Wreck of Gral's Belly.", completion = "You've dispelled one of two ghosts keepin' this curse going. I thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[94040] = { id = 94040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat and Bone and Soul", description = "We have everything we need for de ritual.\n\nMeet me at de Tooth o' Sargoth. You'll help me get my soul back in one piece, then this curse will finally be over.\n\nMay Gral judge me on de other side for my failures here.", sourceObjective = "Help Loa Speaker Yl'mul complete the ritual at the Tooth of Sargoth.", progress = "Just a few more steps. Need de bones tossed and de water chummed and then my soul will be in one piece again.", completion = "You've helped me a lot, {name}. Thank you.\n\nNow all this can end.", sourceObjectiveStatus = "unverified-source-field" }
quests[94052] = { id = 94052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Domanaar's Plan", description = "If I am to defeat Ziadan, I need information.\n\nMaps, strategy scrolls, battle reports, anything that gives me an edge!\n\nScour the Hate Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles.", objectives = "Enter War Mode and collect 6 Ziadan's Battleplans from chests or slain guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94055] = { id = 94055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Domanaar's Plan", description = "To counter Vidious' foul plans, I need information.\n\nMaps, strategy scrolls, battle reports, anything that turns the battle in my favor!\n\nScour the Grief Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles.", objectives = "Enter War Mode and collect 6 Vidious' Battleplans from chests or slain guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94056] = { id = 94056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise. \n\nShould Ziadan obtain this gift instead, her insufferable gloating would never cease!\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it.", objectives = "Enter War Mode and collect the Golden Vidious Card from a War Supply Crate in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94057] = { id = 94057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise.\n\nShould Vidious obtain this gift instead, his taunts would be incessant.\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it.", objectives = "Enter War Mode and collect the Golden Ziadan Card from a War Supply Crate in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94058] = { id = 94058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Amani Tribe" }
quests[94210] = { id = 94210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathering the Nest", description = "A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.", progress = "Have you met all the local vendors? They have some great furnishings available.", completion = "Did you find any good pieces for your house? We hope to have more vendors visit in the future, so be sure to check back often!", objectives = "Learn where to obtain Decor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94361] = { id = 94361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abundant Life", description = "You are ready, acolyte! Ready to spread your wings or what have you?\n\nI have projected my presence into today's most active and tumultuous lands, rummaging about their natures and environs for areas ripe with abundance. With a little provocation from me, these forgotten corners are blooming bright with glorious harvestables!\n\nSeek me out! A crypt of phantasms in Eversong! A grove of verdant flora in Harandar! Even a quarry of living rock in Voidstorm! And, of course, right here too!", progress = "Temperance, acolyte.\n\nThere is still more abundance to be collected yet.", completion = "Well done, fellow acolyte!\n\nLet our harvests be bountiful, our rewards glorious, and our lives abundant!", objectives = "Complete each Abundance event once. They are located in Eversong, Zul'Aman, Harandar, and Voidstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94363] = { id = 94363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!", objectives = "Talk to a Bouncer in Bizmo's Brawlpub in the Deeprun Tram after using your Blood-Soaked Invitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94370] = { id = 94370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Closer", description = "Do you bring tidings from Numia? She was supposed to be here and help me assess these fair flowers.\n\nShe must be occupied. The naga have encroached on my town and hers... they have kept to the beach so far, but that could change quickly.\n\nWill you check on my friend?", completion = "I will make it up to Fern. Thanks for speaking with her.\n\nAnd now, will you help me subdue this typical Farstrider? Nearly decapitated by a snapdragon, and he's acting like he just finished lunch!", objectives = "Find Numia Golden in Goldenmist Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94371] = { id = 94371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ranger's Dream", description = "Apprentices! Who can keep them tied down?\n\nTaemin was a particularly talented arcanist, but his head was always in the clouds. Or in the woods, really.\n\nInstead of studying, he buried his nose in storybooks! The legends of Eversong! The Rangers of old! Heroes of the Sin'dorei! He couldn't get enough, the dreaming fool!\n\nAnd now... no, he's not dead. Did I imply that?\n\nHe's just run off to join the Farstriders. Check in on him, won't you? See if he's come to his senses?", completion = "It was good of you to check on me, but I'm committed to the Farstriders!", objectives = "Check in on Arcanist Taemin at Farstrider Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94372] = { id = 94372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!", objectives = "Talk to a Grunt in the Brawl'gar Arena in Orgrimmar after using your Blood-Soaked Invitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94379] = { id = 94379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Hearth", description = "It looks like your house is ready for an upgrade. This doesn't normally happen so fast, but you've really made an impression around here.\n\nHead on over to our general contractor for next steps.", progress = "Did you get your house upgraded?", completion = "Did the renovation go well? I hope it gives you a little more room for all the treasures you find in your adventures.\n\nBe sure to visit the general contractor again when you're next ready for an upgrade.\n\nOh, and a letter arrived for you while you were away.", objectives = "Level up your house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94380] = { id = 94380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ranger Captain's Summons", description = "Pardon the intrusion, {name}!\n\nI'm delivering a summons from Ranger Captain Lilatha. She's requested your presence at her staging grounds overlooking the Bazaar near the north gate of Silvermoon.\n\nOur lands are once again under threat and we'll need all the support we can get.\n\nReport to her when you can!", sourceObjective = "Report to Ranger Captain Lilatha in Silvermoon City.", completion = "One threat may be dealt with, but dangers from all sides continue to stir within our borders.\n\nA domanaar highlord rallies the minions of the Void to fill the vacuum of power.\n\nStrange ethereals and their machines encroach on our settlements.\n\nEven the remnants of the Twilight's Blade and local naga tribes have been emboldened by the chaos.\n\nWe could use your expertise in dealing with these threats, and I have just the task to get you started.", sourceObjectiveStatus = "unverified-source-field" }
quests[94381] = { id = 94381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outfitting and Allies", description = "Halduron Brightwing has made sure that our task force is well equipped to handle any threat. I want you to check in with our quartermaster, Maren Silverwing. She will help you get outfitted. \n\nI also want you to talk with our \"liaison.\" She is the troll with the guards. You may already know we are not alone in being targeted. \n\nBrightwing has reminded us that these enemies do not respect borders, so threats to Zul'Aman require our attention just as much as Eversong. We must deal with the troll.", sourceObjective = "Speak with Maren Silverwing and Kul'amara the Fierce.", progress = "When you have time continue to talk with others in our task force. We are prepared to support all of your efforts!", completion = "What did you think of our troll ally? It galls me to work with forces who attacked our lands in the past to defend them now. The enemy of my enemy I suppose. \n\nI will respect her prowess though--she looks like she can hold her own in a fight. Time will tell if she is worthy of my admiration or my ire.", sourceObjectiveStatus = "unverified-source-field" }
quests[94382] = { id = 94382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Problems", description = "To get right to it, I have laid out some lessons and some scout objectives for us as we approach the various dangers we might see in these ritual sites.\n\nI have also marked on your map the location of one of these rituals. Take care, as the magics we have seen woven at these sites can overwhelm even the most stalwart warrior.", sourceObjective = "Investigate the Ritual Site Reports and then disrupt a Ritual Site in Eversong Woods or Zul'Aman.", progress = "Were you successful?", completion = "I hope you now respect the dangers posed by great rituals. \n\nI fear though that these sites have the potential to be an even greater danger as we investigate them more and new challenges present themselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[94383] = { id = 94383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Interest", description = "I am here at the behest of the great Zul'jarra! May she lead her people to greatness.\n\nWe face dire threats. Your Captain General is focused on the martial stakes, but the terrible magics unleashed recently pose an even greater danger. Our scouts have discovered rituals that risk ruin for us all.\n\nYour Ranger Captain has recruited the Lady Darkglen, who appears to be a knowledgeable and capable ritual expert.\n\nSeek her out in the tent nearby to find out how best to approach these ritual sites.", sourceObjective = "Check in with Lady Darkglen.", completion = "Kul'amara is such a fascinating individual. Did you know she fights on the front lines while also studying a multitude of rituals? It's such an incongruity and I love it.\n\nAre you ready to stop these rituals that Kul'amara has warned us about?", sourceObjectiveStatus = "unverified-source-field" }
quests[94385] = { id = 94385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Assaults: Eversong Woods", description = "We are seeing a Void Assault in Eversong. We need you to head out immediately to counter these threats. I will mark the strikes on your map as our scouts identify them and direct your efforts from here.", sourceObjective = "Disrupt the Void Strikes around Eversong Woods.", progress = "We must stay vigilant!", completion = "I knew you were key to our efforts and the right person to counter these threats! We face a diverse group of enemies, so someone who can react to new situations will continue to excel among our ranks.\n\nI look forward to working with you on our next assignment, but stay vigilant! These threats do not show signs of waning.", sourceObjectiveStatus = "unverified-source-field" }
quests[94386] = { id = 94386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Assaults: Zul'Aman", description = "My scouts report a Void Assault in Zul'Aman. We need your help to counter these threats. \n\nI will direct you, and my scouts will continue to mark new activities on your map.", sourceObjective = "Disrupt the Void Strikes around Zul'Aman.", progress = "We will triumph over these foes!", completion = "The Ranger Captain's faith in you is well earned. My people are also indebted to you for your assistance. \n\nI look forward to working with you again. My scouts do say that strikes still continue, so stay vigilant out there.", sourceObjectiveStatus = "unverified-source-field" }
quests[94388] = { id = 94388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Time's a Choice", description = "A little lesson. Trying to fool me twice is a grave error.\n\nMy dim-witted pupil has yet to return from their rendezvous with their acquaintance. Normally I would not bat an eye, but he has a journal of mine. I want that journal back.\n\nWould you be a dear and remind him?", completion = "<Magister Meledor appears to be lost in thought...>", objectives = "Remind Magister Meledor in the West Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94390] = { id = 94390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: A Hunter's Regret" }
quests[94391] = { id = 94391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Push Back the Light" }
quests[94393] = { id = 94393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Career Counseling", description = "How good are you at teaching, {name}?\n\nOne of my pupils, Kyltus, has been having particular trouble with deciding what path along the road of life he wants to pursue. \n\nPerhaps a talk with you will aid his tumultuous heart?", completion = "Instructor Thalendir sent you?! I will have to give him my apologies.\n\nBut I am glad you are here. Could you lend me an ear?", objectives = "Check in on Kyltus Bloodburn in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94396] = { id = 94396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down a Peg", description = "There seems to be a problem student at the academy.\n\nI have heard reports that a student, Tytalor Goldenblade, is stirring up trouble in Sunstrider Isle. I'd go myself but I have my hands full running practice here already.\n\nCould you go check on him and... educate him of his misgivings?", completion = "Truly, I am incredibly talented!\n\n<Tytalor appears to be lost within his own thoughts.>", objectives = "Check in on Tytalor Goldenblade in the Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94408] = { id = 94408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Ziadan. Bring me those contracts, and I will pay you what their loyalty once cost her.", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold.", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94409] = { id = 94409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Contract of Service", description = "It is not honor or glory that drives your kind to war...it is gold. You and your enemies are always paid for the blood you spill upon the battlefield.\n\nEvery enemy you slay in Slayer's Rise carries a contract from Vidious. Bring me those contracts, and I will pay you what their loyalty once cost her", progress = "Are you here to deliver their contracts?", completion = "See I was correct. In the end the price of blood is always in gold.", objectives = "Collect 10 Contracts of Service off slain players in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94415] = { id = 94415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plumbing the Void", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94416] = { id = 94416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rehoming Technology", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has allowed you to take a small selection of our technology back to your world, if you choose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94417] = { id = 94417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crests of the Dawn", description = "Using what I've learned from Silvermoon's artisans, Cuzolth and I can infuse your gear with additional power!\n\nPowerful equipment requires Dawncrests to upgrade it to its full potential. These crests are rewarded through many different activities. Dawncrests have five tiers, and more dangerous tasks reward you with higher-tier crests. Adventurer Dawncrests are the lowest tier, but still quite powerful!\n\nBring me thirty Adventurer Dawncrests and we can help you upgrade your gear further.", progress = "If you're having a hard time finding Adventurer Dawncrests, you can search for hidden treasures around Eversong, Zul'Aman, Harandar, and Voidstorm. There's no shortage of those treasures!", completion = "This is wonderful. I'm excited for you to grow in power!\n\nAnd to advance my research, of course. But yes, your power is my top priority!", objectives = "Acquire 30 Adventurer Dawncrests by defeating unique creatures, completing world activities, or by looting caches. Speak to Cuzolth to upgrade an Adventurer track item using those crests, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94418] = { id = 94418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crest Transmutation", description = "Did you know that crests can be transmuted into different tiers?\n\nIf you find yourself with crests that are too powerful for the gear you've acquired, I can help you transmute those crests into lower tiers that you can use.\n\nAnd once all of your gear is sufficiently powerful, I'll be able to transmute your spare lower crests into higher ones!\n\nLet's practice the transmutation process. Here's a few Veteran Dawncrests. Speak to me and I can transform them into Adventurer Dawncrests for you.", progress = "If you lose those Veteran Dawncrests, you can find more from powerful creatures around Eversong, Zul'Aman, Harandar, and Voidstorm. I've heard there's quite a variety of them!", completion = "Remarkable!\n\nKeep in mind I can only transmute crests into a higher tier when you have outgrown their usefulness, and it will be a costly process. Thank you for all of your help, {name}!", objectives = "Bring 10 Veteran Dawncrests to Vaskarn in Silvermoon, then trade them for a Bundle of Adventurer Dawncrests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94423] = { id = 94423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum Secure", description = "Our control here is only the beginning. Xal'atath has left other pockets of anomalies across the land. The defenses we've devised here can be used to secure those areas as well.\n\nTravel to Sunkiller Sanctum and construct five additional defenses to solidify our hold on that location.\n\nI will supply the Stormarion Core necessary to activate those defenses.", objectives = "Deploy 3 defenses at Sunkiller Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94425] = { id = 94425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleed the Spire" }
quests[94430] = { id = 94430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventuring Gear", description = "{name}, you're just in time! I was exchanging research notes with the artisans here in Silvermoon all day. Did you know they can infuse weapons and armor with the power of the dawn itself? Fascinating!\n\nI've been itching to put some of these new techniques to the test. Bring me a piece of Adventurer equipment and I'll let you know what we need to make it more powerful.\n\nThere should be plenty of people in Silvermoon and beyond willing to reward you with some Adventurer equipment in exchange for your aid.", completion = "This piece of equipment will be perfect!\n\nI can help you make this more powerful, but we'll need some reagents.", objectives = "Obtain a piece of Adventurer track gear, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94432] = { id = 94432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Equipment", description = "We have only just begun to scratch the surface of how powerful your gear can become!\n\nHowever, every piece of equipment has a limit to how much it can be upgraded. The more powerful an item is at its baseline, the more powerful it will become as we upgrade it. An item's upgrade track determines which crests we must use to upgrade it.\n\nBring me a piece of Veteran equipment this time along with ten Veteran Dawncrests. Just like before, Cuzolth will help you upgrade the item using those crests.", progress = "If you're having trouble finding a piece of Veteran equipment, try completing a Heroic dungeon or a challenging weekly activity in Eversong, Zul'Aman, Harandar, or Voidstorm. You can find more powerful gear this way!", completion = "You're a natural! It looks like you have a handle on things already.\n\nEvery time you want to upgrade a piece of equipment, the process works the same way. Bring us the item and the crests that go with it, then Cuzolth will help you upgrade it.", objectives = "Obtain a piece of Veteran track gear and 10 Veteran Dawncrests. Speak to Cuzolth to upgrade a Veteran track item using those crests, then return to Vaskarn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94444] = { id = 94444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose a Path", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path.", objectives = "Talk to Chromie in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94445] = { id = 94445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose a Path", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Say, you look like someone who appreciates the great outdoors! Elwynn is lovely this time of year.\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay, {name}!", completion = "Carry your traditions with pride, for their roots intertwine within you.\n\nAln'hara bless your path.", objectives = "Talk to Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94446] = { id = 94446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nightmarish Task", sourceObjective = "Complete Nightmare Hunts in Prey.", completion = "You reek of anguish.\n\nExquisite.", sourceObjectiveStatus = "unverified-source-field" }
quests[94447] = { id = 94447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ophidia the Broodmother", description = "Zawadi safe, eh? Good. No harm should come to her. We need to deal with these oversized worms.\n\nJust over there, by de beach, is one of their broodmothers. Vile creature! Responsible for all de eggs you see 'round here. Kill her. Their invasion will stall, giving my people more time to organize a strike.\n\nI need to tend my wounds. I will hide and wait for you.", sourceObjective = "Kill Ophidia the Broodmother.", completion = "Wa'kani may have blundered dis mission, but she was right to have you defeat de egg-layer. Dis is a significant blow to de expansion plans of de Children of Ula'tek here in de mire.\n\nNdamu and de other scouts remain missing, however. I fear de murlocs have them.", sourceObjectiveStatus = "unverified-source-field" }
quests[94450] = { id = 94450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twenty Five Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons.\n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
