quests[94452] = { id = 94452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seventy Five Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons. \n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94453] = { id = 94453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Hundred Percent Completed", description = "We're still getting things setup for rewarding endeavors. This is a temporary quest to grant you community coupons. \n\ncommunity coupons will normally be earned by completing endeavor tasks, not via a quest like this." }
quests[94455] = { id = 94455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home at Last", description = "It's time to cross the threshold into a new chapter.", objectives = "Approach your front door and enter your new house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94457] = { id = 94457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Battlegrounds", description = "Battlegrounds stand as crucible where soldiers clash for honor, resources, and glory.\n\nEach victory hones your skill and strengthens your resolve.\n\nGo, test yourself against worthy foes and bring pride to your banner.You will learn:", sourceObjective = "Complete any Battleground in Midnight.", sourceObjectiveStatus = "unverified-source-field" }
quests[94464] = { id = 94464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Haranir", description = "You have travelled far and learned much of Aln'hara's grace.\n\nIt is time to return home and share the wisdom you have earned with your people.", completion = "You have seen many battles and met many peoples. Your journeys continue to bring us closer to the wisdom and grace of Aln'hara. \n\nSince you left, roots and vines began to rapidly grow within your old home. Eventually, their purpose became clear: armor, grown for you from the roots of the great trees as a blessing from Aln'hara herself!\n\nWear it with pride as you continue your journey, {name}. Thank you.", objectives = "Tell Orweyna of your travels at the Den in Harandar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94469] = { id = 94469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "Thanks to you, the singularity anchor survived another assault. Take this as a sign of our appreciation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94470] = { id = 94470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cluster of Voidlight Marl" }
quests[94471] = { id = 94471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trove of Voidlight Marl" }
quests[94474] = { id = 94474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Vault", description = "In wake of recent events, the Vanguard of the Light has recovered and preserved relics of exceptional power and craftsmanship. To safeguard these treasures from prying eyes, the Magisters of Silvermoon have conjured a vault within Silvermoon's bank.\n\nOnly the most proven of champions may earn the right to draw from its splendor. If the Light deems you worthy, you may be bestowed an artifact of great power.", objectives = "Obtain a piece of loot from the Great Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94475] = { id = 94475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", sourceObjective = "Collect 3 Echoes of Radiance within The Voidspire on Normal difficulty.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, {name}--I cannot guarantee your safety.", sourceObjectiveStatus = "unverified-source-field" }
quests[94476] = { id = 94476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", sourceObjective = "Collect 3 Echoes of Radiance within The Voidspire on Heroic difficulty.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, {name}--I cannot guarantee your safety.", sourceObjectiveStatus = "unverified-source-field" }
quests[94477] = { id = 94477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voidspire: Flicker in the Hollow", description = "There's little light in these lands. What remains is fractured, hidden, or fading.\n\nFetch me Echoes of Radiance and I will grant you passage where no path should exist.", objectives = "Collect 3 Echoes of Radiance within The Voidspire on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94478] = { id = 94478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of Silvermoon Court" }
quests[94492] = { id = 94492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Slayer's Duellum", sourceObjective = "Speak with Thraxadar in Masters' Perch.", sourceObjectiveStatus = "unverified-source-field" }
quests[94519] = { id = 94519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Hope in the Light?", description = "Ever since the terrible events of the Voidspire, Arator has suffered. He has kept to himself, or prayed alone at the Dawnwell.\n\nWe all feel the loss of Alleria and Turalyon, but Arator only reunited with them recently, after their long fight against the Burning Legion.\n\nI worry that if he is left to his own thoughts for too long, he may not come out of this the same.\n\nLet us go to the Dawnwell and check on him.", sourceObjective = "Check on Arator at the Dawnwell with Magister Umbric.", completion = "If the Light will not give me answers, then I need to find another way.\n\nThe Twilight's Blade must know something of where Xal'atath has gone, or what she's planning next. If we can get them to talk, then we can stop her.\n\nI have to believe this.", sourceObjectiveStatus = "unverified-source-field" }
quests[94520] = { id = 94520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resurgence in Deatholme", description = "While we cannot know yet where Xal'atath has gone, or if Alleria and Turalyon are still alive, we can still pursue information.\n\nRiftblade Maella has kept me up to date on the Twilight cultists. They have been gathering strength, gathering numbers, and seem to be searching for... something. Now is the time to act.\n\nLet us travel to the Ruins of Deatholme and see why the cultists there have reinvigorated themselves.", sourceObjective = "Meet Arator at the Ruins of Deatholme.", completion = "I thought all our fighting would have reduced the numbers of the Twilight's Blade, but it seems to have done nothing.\n\nIf anything, there are more of them now! What could they be up to?", sourceObjectiveStatus = "unverified-source-field" }
quests[94521] = { id = 94521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Direct Method", description = "The information we need has to be here! We just need to get it from the Twilight's Blade.\n\nThere's nothing wrong with the direct method. Apply force, and see what you can learn.\n\nI brought Benthar's Scarlet Spire, the relic we rescued from the Scarlet Crusade. It's already been used to help protect the Sunwell, and maybe it can help us here.", sourceObjective = "Obtain clues from Twilight's Blade cultists in the Ruins of Deatholme.", progress = "Every time we make some progress, it feels as though it slips away again.", completion = "They were expecting something more from Xal'atath?\n\nShe's a monster and a manipulator. How could they have thought she would do anything other than abandon them?", sourceObjectiveStatus = "unverified-source-field" }
quests[94522] = { id = 94522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Always Write It Down", description = "An organization as widespread and diverse as the Twilight's Blade must need to write down their objectives.\n\nOr at the least, whatever they have collected should shed light on what they're up to. \n\nSee if you can find anything that points to their current direction.", sourceObjective = "Investigate in the Ruins of Deatholme.", completion = "Something doesn't add up.\n\nIt makes no sense that the Twilight's Blade would be moving Amani artifacts around.\n\nI wish Umbric were more willing to use his magic at a time like this. We could be racing the clock right now and have no idea.", sourceObjectiveStatus = "unverified-source-field" }
quests[94523] = { id = 94523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Poor Beautiful Self", description = "Oh, please don't hurt me!\n\n<The pathetic voidling cowers at the sight of you.>\n\nIt's not my fault. I could have gotten them out of this.\n\nIt's those new commanders! They have led the Twilight cult down the wrong path.\n\nGlaivh is the worst of them. If he was gone, perhaps, perhaps...", sourceObjective = "Kill Aspirant Commander Glaivh and return to the Pathetic Voidling.", completion = "<The pathetic voidling eyes you with wary curiosity.>\n\nYou destroyed him? There is hope...\n\nPerhaps I can share what I know.", sourceObjectiveStatus = "unverified-source-field" }
quests[94524] = { id = 94524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under New Management", description = "The rank-and-file Twilight's Blade didn't have much to tell us, but their new leadership may know more.\n\nYou've already bested one of them. Let's see if there are others who also aspire to lead, and learn what they know.\n\nYou can still use the Scarlet Spire on them. If Umbric won't use his magic, then perhaps the Light will make them talk.\n\nThey should be below us, in the chasm.", sourceObjective = "Slay Aspirant Commanders in the chasm beneath the Ruins of Deatholme.", completion = "A gateway? What could the Twilight's Blade cultists mean by that?\n\nAnd why can't they follow? Is that where Xal'atath has gone? Through some kind of gateway?\n\nToo many questions, and not enough Twilight's Blade who know the answer.", sourceObjectiveStatus = "unverified-source-field" }
quests[94525] = { id = 94525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Comeback Story", description = "No one notices a creature like me...\n\nNo one appreciates how much I have lost.\n\nBut in that underestimation... knowledge.\n\nHelp me regain some strength, and I will regain the words you need.", sourceObjective = "Feed the Voidling from latent voidrifts in the lower Ruins of Deatholme.", completion = "I knew there was something familiar about that voidling. \n\nBut now that we have him cornered, he can tell us what we need to know.", sourceObjectiveStatus = "unverified-source-field" }
quests[94526] = { id = 94526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verifiably Untrustworthy", description = "As soon as we met that little voidling, I thought there was something I recognized. \n\nHow Antenorian survived, I know not. But it's clear that we cannot let him get away. We need to know what he knows, and then his time on Azeroth should truly be ended.\n\nCome, let's get what we need and finish this.", sourceObjective = "Defeat Antenorian.", completion = "No!\n\nArator...\n\nI cannot lose him too. Not after Alleria.", sourceObjectiveStatus = "unverified-source-field" }
quests[94527] = { id = 94527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null Space", description = "Arator jumped after Antenorian like a man possessed. He's so blinded by this crusade, he... he must not know how dangerous it is for someone like him to simply leap into the Void blindly.\n\nNo, we must think calmly about this. Analyze the situation.\n\nWe have no way of knowing what's on the other side of that portal. \n\nBut we must go in. We must find Arator.", sourceObjective = "Follow Antenorian into the Unknown.", completion = "What... what just happened?", sourceObjectiveStatus = "unverified-source-field" }
quests[94528] = { id = 94528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carving Out Room", description = "I need a moment, after what we just went through. I feel like my body is fighting with itself.\n\nBut we're in hostile territory. I can't let us fall to enemies just because I was... because I had to jump in after him. We need to keep Umbric safe.\n\nCan you clear out the Twilight's Blade around us to give us some room to recover?", sourceObjective = "Slay Twilight's Blade cultists in Speaker's Rest.", progress = "It's like one half of me is at war with the other half.", completion = "Thank you. I think I've got a hold over my senses now.\n\nIt's so strange. Antenorian called me a child of the Light and yet...\n\n<Arator looks at his hands, pondering.>", sourceObjectiveStatus = "unverified-source-field" }
quests[94529] = { id = 94529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Shadow Looms", description = "We are lucky to have survived that tear through the Void, but now we are presented with an opportunity.\n\nAntenorian must have been going somewhere in this direction, which is why we find ourselves no longer in Eversong. But we interrupted his journey, and he is still here somewhere.\n\nI can feel it like a chill along my spine.\n\nSee if you can find any more information from the Twilight's Blade here. What of that gateway that Antenorian spoke of? What of those Amani prophecies?", sourceObjective = "Investigate Twilight Correspondence.", progress = "Have you found any more of the Twilight Blade's plans?", completion = "So Xal'atath opened a gateway through the Darkwell, and the Twilight's Blade are awaiting the arrival of some Dark General.\n\nHow do they know it is coming? And where will it appear?\n\nThis is growing more complicated by the moment, and more alarming.", sourceObjectiveStatus = "unverified-source-field" }
quests[94530] = { id = 94530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Void", description = "I've been able to trace where Antenorian fled. He is more powerful than he was before, after that jaunt through the void space. \n\nFortunately, this makes him easy to track. He's below us, in an open cavity underground. I can open a portal there.\n\n<Umbric glances over at Arator.>\n\nI hope that we can put an end to this, and Arator is no worse for wear. When we started this, I thought we would find a few scrolls, uncover their plan, and put a stop to it ourselves.\n\nI did not anticipate this.", sourceObjective = "Enter the tomb and permanently defeat Antenorian.", completion = "It's all a trap. Ula'tek's death will only unleash something worse.\n\nThe Twilight's Blade knew this. And we were blind.\n\nI was blind.", sourceObjectiveStatus = "unverified-source-field" }
quests[94531] = { id = 94531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Mother, Like Son", description = "<Arator quietly seethes.>\n\nWe need to tell Lor'themar what we've learned. Not because I want to stop looking for Xal'atath, but this is important.\n\nCome, let's leave Zul'Aman and return to Silvermoon.", sourceObjective = "Report to Lor'themar Theron in Silvermoon.", completion = "<Lor'themar shakes his head.>\n\nArator is strong. Headstrong, sometimes. But we must focus on what's immediately before us. \n\nWith Ula'tek's death, something even worse emerges on our borders. We must be ready.\n\n<Lor'themar's expression hardens.>\n\nWith all the forces we can muster.", sourceObjectiveStatus = "unverified-source-field" }
quests[94571] = { id = 94571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of History" }
