quests[94622] = { id = 94622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work It", description = "The Trial of Style gives us the opportunity to look good, {class}.\n\nThe camera makes sure we keep looking good. \n\nSo focus on me and my camera, follow my directions and I'll make sure you look fantastic!", sourceObjective = "Focus on the photographer and follow their directions.", progress = "Focus on me and follow my directions.\n\nI'll make sure you look great.", completion = "The camera doesn't lie, {name}. \n\nYou are one stylish {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[94623] = { id = 94623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building the Voidforge", description = "I have been considering how I may offer you greater strength, my friend. I've come up with something, but I need your help building a proper Voidforge.\n\nWhat? Oh, fear not, all my ulterior motives are still aligned with your cause. For now.\n\nTo begin, I need one Elementary Voidcore. You will be able to find shards from the more powerful foes you habitually encounter. Inflict your usual violence, return the shards, and I can weave them back into a true Voidcore to serve as the forge's foundation.You will learn:", objectives = "Deliver Elemental Voidcore Shards from Midnight Season 1 raid bosses, Bountiful Delves, and Mythic+ dungeons to begin constructing the Voidforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94625] = { id = 94625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Elementary Voidcore", sourceObjective = "Collect 3 Elementary Voidcore Shards from Midnight Season 1 raid bosses, Bountiful Delves, and Mythic+ dungeons to continue constructing the Voidforge.\n\nThe Voidforge will grant access to Nebulous Voidcores, used to obtain powerful items from raid bosses, Mythic+ dungeons, Bountiful delves, and Nightmare Prey.", progress = "You certainly weren't in any rush with this one, {name}. I suppose the gates of time can't be rushed, can they?", completion = "Excellent. One more Elemental Voidcore for the Voidforge!", sourceObjectiveStatus = "unverified-source-field" }
