quests[94677] = { id = 94677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Rootwarden", progress = "The Rootwarden should be here. We must find out what would be so pressing that would take him away from his responsibilities.", completion = "This is troubling news. The Lightbloom hasn't seemed to affect any haranir thus far. Has it somehow infested the Rootwarden? Or is this his pride speaking? He's always been a zealous one, but...\n\nWe must move quickly.", objectives = "Find 3 Ruia's Musings in Har'alnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
