quests[94790] = { id = 94790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Research Console: Exploring the Void", description = "No rest for the researchers, as they say.\n\nAs much as I would love to go traipsing around this blasted voidscape, I need to remain at this post. But you! You can be our eyes and ears in the abyss.\n\nGo and explore the Voidstorm, maybe we can find some additional samples to feed into the console.", completion = "More samples, excellent! The console hungers...", objectives = "Complete 3 World Quests for Void Researcher Anomander in Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94794] = { id = 94794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Fashion Funding", objectives = "Thank you for your assistance. Please accept this token as thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94795] = { id = 94795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Agents of the Shield" }
quests[94796] = { id = 94796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing Curse Resistance", description = "Now that the Hoarder is gone, the fish population has boomed. There's a flood of fish with no curse at all!\n\nCaptain Tokka wants to study these curse-resistant fish. Go and collect a few of their livers so we can see what keeps them swimming.\n\nIf we want to use the venom-curse for ourselves, we need more cursed fish!", sourceObjective = "Collect 6 Whole Uncursed Livers in the Serpent's Tail.", progress = "Captain Tokka is always experimenting with something. He keeps jars of cursed fish guts. H-he's sure to like whatever you find, {name}!", completion = "<Second Mate Sluggs stares at the fish livers with wide eyes.>\n\nO-oh, thank you, {name}! Captain Tokka will... really like those.\n\n\n\nYou can set them down there. Thank you. Truly.", sourceObjectiveStatus = "unverified-source-field" }
quests[94798] = { id = 94798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ssak'mozek's Desire", description = "Captain Tokka finished the lure for Ssak'mozek. It's time to kill the beast!\n\nTake the lure into the marsh, near the wreck of Pa'ku's Talon. Ready yourself, then place it on the rocks there.\n\nSsak'mozek will be drawn to the lure. Kill it.", sourceObjective = "Lure then slay Ssak'mozek in the Serpent's Tail.", completion = "<Second Mate Sluggs shakes with excitement.>\n\nThe lure worked! Just like Captain Tokka showed me. And it's all thanks to you.\n\nWe have more work to do, {name}, but you should take a moment to celebrate your victory. Until tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[94800] = { id = 94800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushed Crabs", description = "Hegvosh the Hoarder is back!\n\nHe's already started killing anything that gets in his way. This time, he's stomped on all of our crab traps in the south.\n\nSalvage any working trap pieces you find. We'll need to rebuild them.", sourceObjective = "Salvage 8 crab trap pieces in the Serpent's Tail.", progress = "We trap crabs for food, mostly. Even Captain Tokka needs to eat! He also likes to create new and, uh, interesting ways to trap the crabs. Mostly using venom-cursed needles.", completion = "I'll take these to Captain Tokka so we can get the traps put back together.\n\nThe Hoarder may be reducing our food supply on several fronts, but he'll never understand the curse like Captain Tokka!", sourceObjectiveStatus = "unverified-source-field" }
quests[94802] = { id = 94802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death from the Dead", description = "Ssak'mozek always has three heads. Captain Tokka's lure targets each of them.\n\nThe next piece of the lure is ethereal beads from ghosts on the Isle. They exist somewhere between here and the beyond and shine in just the right way that the hydra can't ignore them.\n\nYe can find some of these beads in the Crypt of the Lost Mason. Be careful--the ghosts may not like you entering that place.", sourceObjective = "Collect 8 Ethereal Bead Strands in the Crypt of the Lost Mason.", progress = "Captain Tokka likes to say \"there's no taboos in venom fishin'.\" He's right of course! But if you maybe have concerns about sort of robbing graves, I've dug around in that crypt over and over again. The beads are more ghost than real artifact.", completion = "See how the beads shine without any light hitting them? Ssak'mozek will be able to see this from far underwater. Smells, sight... two pieces of the lure ready to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[94803] = { id = 94803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going for the Crown", description = "The final pieces of Captain Tokka's hydra lure are feathers from the Children of Ula'tek themselves.\n\nSsak'mozek is trained to listen to the orders of these monsters. It lies in wait for them to call it from the murky depths. The lure can't work without something tying it to Ssak'mozek's masters.\n\nAny of the children at the Gate of the Eastern Fang will have feathers perfect for the lure. Bring as many as you can.", sourceObjective = "Collect 7 Vibrant Crownfeathers in the Serpent's Tail.", progress = "Do you have the last piece of Ssak'mozek's lure? We need feathers--the brighter, the better.", completion = "That's everything we need. I'll craft the lure. Next, we take down that monster!", sourceObjectiveStatus = "unverified-source-field" }
quests[94804] = { id = 94804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Collection of Rot", description = "Have you noticed fewer fish on the south side of Atal'Utek lately? That's the Hoarder at work.\n\nHe's this big ugly sea giant we can't seem to shake. You'll know you've found him when you see piles of dead fish rotting away.\n\nMake him think twice about taking too much from these waters.", sourceObjective = "Kill Hegvosh the Hoarder in the Serpent's Tail.", completion = "You've slain the Hoarder! We have a window to fish our fill, thanks to you. You should get back out there!", sourceObjectiveStatus = "unverified-source-field" }
quests[94805] = { id = 94805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Hoard, Poached", description = "The Children of Ula'tek eat venom-cursed fish straight from the water. Now that we've made the fish stronger, the children have gone into a feeding frenzy!\n\nCaptain Tokka says to stop the poaching. The children have plenty of venom already!", sourceObjective = "Kill 9 Children of Ula'tek in the Serpent's Tail.", completion = "I could hear the angry hissing from here, {name}! Hopefully the Children of Ula'tek will stay away from our fishing spot for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[94806] = { id = 94806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wriggling and Wet", description = "Captain Tokka wants us to fish for Ssak'mozek.\n\nThe Children of Ula'tek raise a hydra more vicious and venom-cursed than all the rest. We've caught and killed it before, but they always raise another and give it the same name: Ssak'mozek.\n\nWe're going to craft one of Tokka's best lures to draw it in.\n\nStart by collecting the legs of leeches. When broken, they have a smell the children and their creations cannot resist.", sourceObjective = "Collect 36 Pungent Leech Legs in the Serpent's Tail.", progress = "Don't break the leech legs, if you can. We need to break them right before we make the lure so the smell is fresh.", completion = "These will do excellent! Ssak'mozek lurks beneath the water. The smell from these leech legs will help draw it to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[94808] = { id = 94808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Midnight - Normal Random - 1st" }
quests[94809] = { id = 94809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Midnight - Normal Random - Nth" }
