quests[94831] = { id = 94831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Idol in Hand", description = "<The idol appears to be a figure of Ohn'ahra carved from serevite, an ore used in many titan temples.\n\nPreservationist Kathos would surely be interested in this.>", objectives = "Return the Idol of Ohn'ahra to Preservationist Kathos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94834] = { id = 94834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Abundance", description = "<This idol proves the depth of your bond with abundance.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Dundun.>", completion = "Ah, an Idol of Abundance.\n\nDe lord of glory and plentitude must favor you highly above his many other acolytes.", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94835] = { id = 94835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Early Morning Training", description = "Interested in enrolling in a training program? Some of the strongest warriors have emerged from hard work and dedication. \n\nWith some practice, {name}, you surely can join their ranks. Begin today!", sourceObjective = "Win Battlegrounds in Training Grounds or against players.", progress = "You have yet to finish your training for the week.", completion = "Great effort. Return next week for your continued training.", sourceObjectiveStatus = "unverified-source-field" }
quests[94836] = { id = 94836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Late Night Training: Week 1 of 3", description = "Welcome back to this multi-course training - only a few weeks left! Let's put into practice what you learned last week. Go and participate in Battlegrounds in the Training Grounds or against other combatants, then return back to me.", sourceObjective = "Win Battlegrounds in Training Grounds or against players.", progress = "You have yet to finish your training for the week.", completion = "The hard work is paying off I see - great job! Return back to me next week.", sourceObjectiveStatus = "unverified-source-field" }
quests[94837] = { id = 94837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight Training: Week 2 of 3", description = "You're over half way done with your training! Again, let's take some of the lessons you have learned previously and apply them in the battle fields. Enter Training Grounds or Battlegrounds then return to me.", sourceObjective = "Win Battlegrounds in Training Grounds or against players.", progress = "You have yet to finish your training for the week.", completion = "Take note of what you've learned and prepare for your final training.", sourceObjectiveStatus = "unverified-source-field" }
quests[94838] = { id = 94838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Training: Week 3 of 3", description = "This is the final week of training. Take all of the lessons you've learned and put them into practice in the Training Grounds or against other players. Once complete, speak with Captain Dawnrunner in Falconwing Square.", sourceObjective = "Win Battlegrounds in Training Grounds or against players.", completion = "Well done completing the training program. For your hard work, take this! As you continue your journeys in battle, you can return back to me to become better equipped.", sourceObjectiveStatus = "unverified-source-field" }
quests[94839] = { id = 94839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of Peril", description = "<This idol proves the depth of your bond with peril.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Puul.>", completion = "An Idol of Peril...\n\nMany shy away from de realm of perils. There is much danger surroundin' de immense power Puul blesses their worshippers with.\n\nWill you risk your life for it?", objectives = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94840] = { id = 94840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of The Depths", description = "<This idol proves the depth of your bond with the Depths.\n\nSpeak with Du'gal at the Altar of Blessings in Amani'Zar to begin worshipping Pahk.>", sourceObjective = "Speak with Du'gal at the Altar of Blessings in Amani'Zar.", completion = "Jeju passed his Idol of de Depths on, did he?\n\nThere are not many souls willin' to brave de world beneath our ocean waves. But Pahk watches over all who surrender themselves to de currents--alive or otherwise.", sourceObjectiveStatus = "unverified-source-field" }
quests[94844] = { id = 94844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: For My Horde", description = "We must repel this attack.\n\nYour Horde is strong. You do not give in to the hypocritical claims of the Alliance. You do not let them besmirch your honor.\n\nI want my forces to learn from you. Go, take this Voidclarion. Use it to inspire my void minions.\n\nLet them see the power of the Horde.", completion = "Good. My minions must grow stronger.", objectives = "Empower 8 Hatebound forces at the Bastion of Might in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94845] = { id = 94845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: The Bastion of Might", description = "Vidious presses an attack. I do not see this Alliance he recruited, but monsters.\n\nIllogical. Vidious would not recruit another force until we had our fun with the recent additions.\n\nFight these monsters. Find out what they are. Bring me evidence.\n\nPerhaps you need a cause to fight for beyond amusement? If Vidious tires of me, he will turn his conquest to Azeroth next. You'll want to stop that, right?\n\nThen aid me.", progress = "What trickery have you found?", completion = "Shadowgraft? Pathetic.\n\nOnly domanaar with less skill and intelligence use it. It empowers creatures--makes them blind with violent urges.\n\nBut the creatures lose all cunning. All interest. It is a single flavor, not the complex notes of heartache and betrayal. It is boring.", objectives = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94847] = { id = 94847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations Underway", description = "As you may or may not recall, I once helped young paladins obtain their first armored mount.\n\nIt was a tedious task that involved months of obtaining materials and sending them all over Azeroth.\n\nThankfully, times have changed and we now have most of those materials at hand. That being said, I wish to help you obtain a new mount, something worthy of your title as Highlord.\n\nIn order for us to begin, I only require that you obtain a barding for us. Something strong, thick, and heavy.", completion = "<Grayson examines the barding.>\n\nThis is... well, a good start, Highlord. But I think it will have to be strengthened a bit.", objectives = "Obtain a Stonehide Leather Barding from a leatherworker. You may also obtain it from the auction house if you're not a leatherworker or don't know a leatherworker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94848] = { id = 94848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Pre-Provoked Violence", description = "Vidious, using shadowgraft? Unbelievable. He is better than this.\n\nHow dare he disappoint me.\n\nI need no shadowgraft to convince mighty {class}s like you to fight for me.\n\nShow him the error of his ways before he disappoints me further and abandons this conflict in favor of helping Xal'atath conquer Azeroth.\n\nTake the fight to him. Siege his bastion. And if you do not wish to stain your hands with Alliance blood, there are many void minions awaiting your prowess.", completion = "So, Vidious is also under attack by shadowgrafted monsters? \n\nI see. \n\n<Ziadan almost smiles.> \n\nSo, he did not betray my expectations after all. Perhaps we keep him alive a little longer. \n\nBut there is a third. An interloper.", objectives = "Slay Void creatures or players in the Bastion of Valor in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94849] = { id = 94849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: A Familiar Grudge", description = "Vidious will have a favorite, much like I do: a mortal from your world filled with grief turned to violence.\n\nThey do not have the support of your leaders, but they will always have support from us domanaar.\n\nFind this favorite. I hear of a warlock that has slain many Horde. I feel their grief wafting in the air. They are so lost in it, they would give up the war to save Azeroth for a chance to kill your people.\n\nGo. Savor the fight.", completion = "Good work. The mortal was blinded by their pain, so they never would have listened to reason. \n\nAll they cared for anymore was the fight.", objectives = "Slay Emrin Sparkpox at the Bastion of Valor in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94850] = { id = 94850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You Build It", description = "If we wish to achieve a sustained connection to Xoroth, we'll need a particularly resilient portal. Unfortunately, we can't just summon this one up from the ground.\n\nI will need you to gather the requisite materials. Once we have them, I will have the mo'arg begin construction at once. \n\nHere's the list of what you'll need.", completion = "Excellent. This Unbending Potion should shore up the Felslate enough to hold the portal's structure, and these Chaotic Spinel crystals should focus the portal's magic nicely.\n\nI will set the mo'arg to work posthaste.", objectives = "Collect 5 Felslate, 3 Chaotic Spinel and an Unbending Potion. These can be gathered and crafted using profession skills or purchased on the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94855] = { id = 94855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidscar Arena: Setting It Aside", description = "So, we have another enemy? One who would get in between me and Vidious?\n\n<Ziadan tightens her fist around her weapon.>\n\nUnacceptable.\n\nThe Voidscar Arena to the north is the most strategic position outside of our bastions. An interloping domanaar will have staged their forces there, I guarantee it.\n\nI can set aside my quarrel with Vidious long enough to deal with this shared threat. Fortunately for you, he hasn't brought his Alliance forces with him.", completion = "Who dares stage forces here? Without announcing themselves?\n\nNoxian? Decimus? We will root them out and make them pay.", objectives = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94865] = { id = 94865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: What Remains of a Temple Broken" }
quests[94866] = { id = 94866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Ours Once More!" }
quests[94867] = { id = 94867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Atal'Abasi", description = "Tolbani and Jehnira have been missin' for some time. Last I heard, dey were scoutin' Atal'Abasi for supplies.\n\nThat area is covered in murlocs. Too many of 'em is dangerous even for an Amani.\n\nFind dem and make sure dey alright!", completion = "Vakala sent you? She was right to think dis place was dangerous.", objectives = "Find Tolbani and Jehnira in Atal'Abasi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94868] = { id = 94868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes Two", description = "Jan'alai is a hen! And that means eggs! It takes two hatchers to safely hatch her eggs. Find Brek's niece - he will teach you both the ceremony." }
